@@ -53,7 +55,7 @@ void FileSystemNoteLoader::deleteNoteResources(const QString &id)
     m_idToApplet.remove(id);
 }

-Note *FileSystemNoteLoader::loadNote(const QString &id, uint appletId)
+Note *FileSystemNoteLoader::loadNote(const QString &id, uint appletId, const QString &syncPath)
 {
     QString idToUse = id;

@@ -78,12 +80,24 @@ Note *FileSystemNoteLoader::loadNote(const QString &id, uint appletId)
         }
     }

+    if (!syncPath.isEmpty()) {
+        // Start an empty or new sync file with what the note had so far
+        QFile syncFile(syncPath);
+        QFile localFile(m_notesDir.absoluteFilePath(idToUse));
+        if (syncFile.size() == 0 && localFile.open(QIODevice::ReadOnly) && syncFile.open(QIODevice::WriteOnly)) {
+            syncFile.write(localFile.readAll());
+            syncFile.close();
+        }
+        return new FileNote(syncPath, idToUse, true);
+    }
+
     return new FileNote(m_notesDir.absoluteFilePath(idToUse), idToUse);
 }

-FileNote::FileNote(const QString &path, const QString &id)
+FileNote::FileNote(const QString &path, const QString &id, bool external)
     : Note(id)
     , m_path(path)
+    , m_external(external)
     , m_watcher(new KDirWatch(this))
 {
     m_watcher->addFile(path);
@@ -98,7 +112,9 @@ void FileNote::load()
 {
     QFile file(m_path);
     if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
-        setNoteText(QString::fromUtf8(file.readAll()));
+        const QString text = QString::fromUtf8(file.readAll());
+        // A sync file may also be written by other programs as plain text
+        setNoteText(m_external && !Qt::mightBeRichText(text) ? Qt::convertFromPlainText(text, Qt::WhiteSpaceNormal) : text);
     }
 }

