+
+import QtQuick
+import QtCore
+import QtQuick.Controls as QQC2
+import QtQuick.Layouts
+import QtQuick.Dialogs as QtDialogs
+
+import org.kde.kcmutils as KCM
+import org.kde.kirigami as Kirigami
+
+KCM.SimpleKCM {
+    property alias cfg_syncFile: syncFileTextField.text
+
+    Kirigami.FormLayout {
+        RowLayout {
+            Kirigami.FormData.label: i18nc("@label:textbox", "Keep note in file:")
+
+            Kirigami.ActionTextField {
+                id: syncFileTextField
+
+                Layout.fillWidth: true
+                Layout.minimumWidth: Kirigami.Units.gridUnit * 15
+                placeholderText: i18nc("@info:placeholder", "No file chosen")
+
+                rightActions: [
+                    Kirigami.Action {
+                        icon.name: "edit-clear"
+                        visible: syncFileTextField.text.length !== 0
+                        onTriggered: syncFileTextField.text = "";
+                    }
+                ]
+            }
+
+            QQC2.Button {
+                icon.name: "document-open"
+                text: i18nc("@action:button", "Choose file…")
+                display: QQC2.Button.IconOnly
+                QQC2.ToolTip.text: text
+                QQC2.ToolTip.visible: hovered
+                QQC2.ToolTip.delay: Kirigami.Units.toolTipDelay
+
+                onClicked: syncFilePicker.open()
+
+                QtDialogs.FileDialog {
+                    id: syncFilePicker
+
+                    title: i18nc("@title:window", "Choose a File for This Note")
+                    fileMode: QtDialogs.FileDialog.SaveFile
+                    acceptLabel: i18nc("@action:button", "Choose")
+                    options: QtDialogs.FileDialog.DontConfirmOverwrite
+                    currentFolder: StandardPaths.standardLocations(StandardPaths.DocumentsLocation)[0]
+
+                    onAccepted: {
+                        syncFileTextField.text = decodeURIComponent(selectedFile.toString().replace("file://", ""))
+                    }
+                }
+            }
+        }
+
+        QQC2.Label {
+            Layout.fillWidth: true
+            Layout.maximumWidth: Kirigami.Units.gridUnit * 20
+            text: i18nc("@info", "Choose a file in a folder synced with Nextcloud, Syncthing or similar to share this note with other computers. Other notes using the same file show the same text.")
+            textFormat: Text.PlainText
+            wrapMode: Text.Wrap
+            font: Kirigami.Theme.smallFont
+        }
+    }
+}
